#include <stdio.h>
#include <string.h>

#define MAXR 105
#define MAXC 105

int R, C;
int h[MAXR][MAXC];
int dp[MAXR][MAXC];
int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};

int dfs(int x, int y) {
    if (dp[x][y] != -1) return dp[x][y];
    int best = 1;
    for (int k = 0; k < 4; k++) {
        int nx = x + dx[k], ny = y + dy[k];
        if (nx >= 0 && nx < R && ny >= 0 && ny < C && h[nx][ny] < h[x][y]) {
            int val = dfs(nx, ny) + 1;
            if (val > best) best = val;
        }
    }
    return dp[x][y] = best;
}

int main() {
    scanf("%d%d", &R, &C);
    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++)
            scanf("%d", &h[i][j]);
    memset(dp, -1, sizeof(dp));
    int ans = 0;
    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++) {
            int cur = dfs(i, j);
            if (cur > ans) ans = cur;
        }
    printf("%d\n", ans);
    return 0;
}
